def find_minimal_edit(s_in, s_out):
    """Find the minimal edit that transforms s_in to s_out"""
    # Simple approach: find first difference and determine what needs to change
    if s_in == s_out:
        return None

    # Find first position where they differ
    min_len = min(len(s_in), len(s_out))
    pos = 0
    while pos < min_len and s_in[pos] == s_out[pos]:
        pos += 1

    # If we've reached end of one string
    if pos >= len(s_in) or pos >= len(s_out):
        # Insertion or deletion case
        if len(s_in) < len(s_out):
            # Insertion
            return (s_in[pos:], s_out[pos:], pos)
        else:
            # Deletion
            return (s_in[pos:], '', pos)

    # Find the substring that needs to be replaced
    # Try to find matching pattern from the beginning
    old_sub = ""
    new_sub = ""

    # Check if we can find a simple substitution
    for i in range(pos, len(s_in)):
        if i < len(s_out) and s_in[i] == s_out[i]:
            break
        old_sub += s_in[i]

    for i in range(pos, len(s_out)):
        if i < len(s_in) and s_in[i] == s_out[i]:
            break
        new_sub += s_out[i]

    return (old_sub, new_sub, pos)

# Analyze each changed pair
changed_pairs = [(0, 'jg', 'k'), (1, 'gyxf', 'gvgvzwxf'), (3, 'ydxd', 'gvzwdxd'), (4, 'ggxgjg', 'gvgvxgvk')]
for idx, inp, out in changed_pairs:
    result = find_minimal_edit(inp, out)
    print(f"Pair {idx}: '{inp}' -> '{out}'")
    print(f"  Minimal edit: old='{result[0]}', new='{result[1]}', pos={result[2]}")
    print()

